INSERT INTO equipos VALUES(498,4,177101,'15061_01EDIF01',NULL,'Edificio. Exterior','Edificio. Exterior','1','-','-','-','','','','Media','-',NULL,35,'Obsérvanse certas fisuras na fachada. Na parte traseira do edificio (cara sueste) o tellado presenta mal estado por humidades.','1.0');
INSERT INTO equipos VALUES(499,4,177102,'15061_01EDIF02',NULL,'Edificio. Interior','Edificio. Interior','1','-','-','-','','','','Baixa','-',NULL,35,'O teito presenta un pequeno deterioro por humidades. Das 10 lámpadas coas que conta a nave principal, 8 están fundidas e teñen un acceso complicado. Obsérvanse certas fisuras no cerramento, de importancia menor.','1.0');
