INSERT INTO equipos VALUES(503,4,177106,'15061_01EDIF06',NULL,'Aseos','Sala Aseos','1','-','-','-','','','','Baixa','-',NULL,35,'Aseos en condicións normais.','1.0');
INSERT INTO equipos VALUES(504,4,188101,'15061_01TUBE01',NULL,'Conducións','Bombeo cabeceira','','-','-','-','','','','Baixa','-',NULL,23,replace('Tubarias en bo estado de conservación. Obsérvanse a ausencia de varios parafusos entre a unión da valvulería e tubaxes.\nInstalouse unha válvula de bypass á saída da impulsión.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(505,4,188102,'15061_01TUBE02',NULL,'Conducións','Pretratamento','','-','-','-','','','','Baixa','-',NULL,24,'Tubarias en bo estado de conservación, sen signos de corrosión ou fugas.','1.0');
INSERT INTO equipos VALUES(506,4,188103,'15061_01TUBE03',NULL,'Conducións','Homoxeneización','','-','-','-','','','','Baixa','-',NULL,25,'Saída de Masko a tanque de homoxeneización. Pequenos puntos de corrosión nas porcas e parafusos.','1.0');
INSERT INTO equipos VALUES(507,4,188104,'15061_01TUBE04',NULL,'Conducións','Biolóxico','','-','-','-','','','','Baixa','-',NULL,26,replace('No reactor biolóxico soamente se dispoñen tubaxes arredor da cámara aerobia para asperxer auga de servizo sobre a súa superficie do reactor. Estas contan coas abrazadeiras correspondentes, observándose un bo estado de conservación. Son fabricadas en PVC, polo que se descarta a presenza de corrosión nas mesmas.\nCompróbase o correcto funcionamento do sistema.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(508,4,188105,'15061_01TUBE05',NULL,'Conducións','Bombeo a FQ','','-','-','-','','','','Baixa','-',NULL,27,replace('As tubaxes presentan un bo estado de conservación, sen fugas nin corrosión.\nDestácase a existencia dunha abrazadeira á saída do bombeo, aparentemente para unir dous tramos de tubaxe. Non se detectan signos de fugas ao redor da mesma.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(509,4,188106,'15061_01TUBE06',NULL,'Conducións','Dosificación reactivos','','-','-','-','','','','Baixa','-',NULL,28,'As canalizacións para a dosificación de reactivos son de plástico. Varían no diámetro entre elas. As que se viron con caudal circulante, non presentaban fugas. ','1.0');
INSERT INTO equipos VALUES(510,4,188107,'15061_01TUBE07',NULL,'Conducións','Flotación','','-','-','-','','','','Baixa','-',NULL,29,replace('Bypass de DAC a floculación mediante tubeira disposta de xeito pouco ortodoxo sobre a plataforma da unidade de flotación.\nDetéctase unha fuga de aire comprimido baixo a liña de flotación.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(511,4,188108,'15061_01TUBE08',NULL,'Conducións','Desinfección','','-','-','-','','','','Baixa','-',NULL,30,'Tanto a canalización de entrada, como a de saída do equipo de desinfección UV son metálicas. Presentan bo estado, sen fugas e sen defectos significativos.','1.0');
INSERT INTO equipos VALUES(512,4,188109,'15061_01TUBE09',NULL,'Conducións','Bombeo a emisario','','-','-','-','','','','Baixa','-',NULL,31,'Presentan bo estado visual, sen corrosión nin fugas.','1.0');
INSERT INTO equipos VALUES(513,4,188110,'15061_01TUBE10',NULL,'Conducións','Supervisión y control','','-','-','-','','','','Baixa','-',NULL,32,replace('As canalizacións do sistema de control de calidade do efluente mediante o turbidímetro son de plástico flexible.\nDurante o funcionamento non se aprecian fugas nin defectos significativos.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(514,4,188111,'15061_01TUBE11',NULL,'Conducións','Lamas','','-','-','-','','','','Baixa','-',NULL,33,replace('Canalizacións metálicas que saen da liña de flotación, e reúnense as lamas nun recipiente metálico que recibe ás lamas do final da liña de flotación e do parafuso de purga. Á saída desde recipiente metálico é nunha tubeira de plástico. Conectan cunha bomba helicoidal que impulsa as lamas por outra canalización de plástico ata o depósito espesador de lamas.\nSae do espesador noutra tubeira de plástico ata a bomba helicoidal cara o depósito de mestura co floculante. A entrada ao filtro banda faise nunha canalización de plástico. Finalmente, impúlsanse as lamas deshidratadas cara o contedor de lamas cunha bomba helicoidal que está conectada a unha canalización metálica.\nDurante o funcionamento, non se detectan fugas na chegada ao depósito espesador nin no sistema de deshidratación.\n','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(515,4,199101,'15061_01VALV02',NULL,'Válvula de seccionamento pneumática','Liña de flotación','1','-','-','-','','','','Baixa','-',NULL,34,'Dado que o parafuso de fondo se atopa fóra de servizo, non se utiliza a válvula de fondo de actuador pneumático. O longo período sen ciclos de apertura e peche diminúe a confianza na súa fiabilidade. Por petición do explotador da EDAR, non se realizan probas neste equipo, considerándose fóra de servizo en conxunto co parafuso de fondo.','1.0');
INSERT INTO equipos VALUES(516,4,199102,'15061_01VALV03',NULL,'Válvula de seccionamento','Bombeo cabeceira','1','VALVULASTIC','DN 150-PN 16','-','','','','Baixa','-',NULL,34,replace('Válvula de talladeira manual en cabeceira bomba 1. Marca Valvulastic DN 150-PN 16.\nCarece de certos parafusos que o unen á tubaxe de saída e válvula anti-retorno de entrada na zona do actuador.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(517,4,199103,'15061_01VALV04',NULL,'Válvula de seccionamento','Bombeo cabeceira','1','VALVULASTIC','DN 150-PN 16','-','','','','','-',NULL,34,'Válvula de talladeira manual en cabeceira bomba 2. Carece de certos parafusos que o unen á tubaxe de saída e válvula anti-retorno de entrada na zona do actuador. Pequenos puntos de corrosión de baixa importancia na unión coa tubaxe de saída.','1.0');
INSERT INTO equipos VALUES(518,4,199104,'15061_01VALV05',NULL,'Válvula de retención','Bombeo cabeceira','1','AVK','DN 150-PN 10','-','','','','','-',NULL,34,'Válvula de retención tipo bola en cabeceira bombeo 1. Carece de certos parafusos que o unen á tubaxe de entrada e válvula de saída.','1.0');
INSERT INTO equipos VALUES(519,4,199105,'15061_01VALV06',NULL,'Válvula de retención','Bombeo cabeceira','1','AVK','DN 150-PN 10','-','','','','','-',NULL,34,'Válvula de retención tipo bola en cabeceira bombeo 2. Carece de algún parafuso na unión coa válvula localizada á saída.','1.0');
INSERT INTO equipos VALUES(520,4,199106,'15061_01VALV07',NULL,'Válvula de seccionamento','Bombeo a emisario','1','VALVULASTIC','DN 150-PN 16','-','','','','','-',NULL,34,'Válvula de guillotina manual en bombeo de emisario bomba 1.','1.0');
INSERT INTO equipos VALUES(521,4,199107,'15061_01VALV08',NULL,'Válvula de seccionamento','Bombeo a emisario','1','VALVULASTIC','DN 150-PN 16','-','','','','','-',NULL,34,'Válvula de guillotina manual en bombeo de emisario bomba 2.','1.0');
