INSERT INTO equipos VALUES(743,4,NULL,'36058_01BOPF02','VBOA','Bomba purga','Purga de lodos - Liña de flotación 2','1','Mono','ALBOSA C-14K','C329560/05',NULL,NULL,'1,3','Esencial','Parafuso helicoidal',NULL,53,'Equipo en bo estado de conservación. Presión de traballo de 10 bar e unha velocidade de rotación máxima de 800 rpm. Como non se identifica a placa do motor coa potencia, mantense a que aparece no inventario previo.','0.636363636363636');
INSERT INTO equipos VALUES(744,4,NULL,'36058_01CALD01','VBOA','Calderín','Sistema DAC 1','1+1','Campiños','-','D2521',NULL,NULL,'-','Esencial','Sen membrana',NULL,50,'Calderín do único sistema de DAC que suministra a mestura de aire e auga cara ás dúas liñas de flotación. Pendente de ser substituído por un calderín novo. Bo estado de conservación. Non ten marcado CEE. A placa de características non é lexible. Conta cunha apertura para o acceso ao interior e o seu mantemento. As válvulas que emprega para encherse ou vaciarse presentan bo estado e non teñen fugas. Ten instalado un sensor de nivel e un manómetro. A dosificación da mestura de auga e osíxeno contrólase mediante unha válvula pneumática. Marca e modelo obtidos do listado de equipos do inventario previo.','1.0');
