INSERT INTO equipos VALUES(755,4,NULL,'36058_01COPR01','VBOA','Compresor','Liña pneumática','1+1','Atlas Copco','LE-75-10-250H','AIW063550',NULL,NULL,'7,5','Esencial','De pistón',NULL,50,'Equipo en bo estado e operativo. Non se poden ler as características do equipo na placa. Presenta pequenos puntos de corrosión na parte superior da caixa. Datos obtidos do listado de equipos do inventario previo.','0.55');
INSERT INTO equipos VALUES(756,4,NULL,'36058_01COPR02','VBOA','Compresor','Liña pneumática','1+1','Atlas Copco','LE-7-10UV-TM 270','ITR0994420',NULL,NULL,'7,5','Esencial','De pistón',NULL,50,'Equipo en bo estado de conservación. O manómetro funciona. Indícase que, a pesar do secadeiro de aire, o equipo conta cun elemento purgador da auga condensada pola humidade co que entra o aire. A caixa dos pistóns e das poleas presenta puntos de corrosión. Non se identifica a placa. Marca e modelo obtidos do listado de equipos do inventario previo. Como potencia dedúcese a mesma do outro compresor, de mesma marca e modelos similares.','0.5');
