INSERT INTO equipos VALUES(758,4,NULL,'36058_01DEPO02','VBOA','Depósito','Homoxeneización 2','1','Cortiplas','-','-',NULL,NULL,'-','Crítico','PRFV',NULL,48,'Depósito en bo estado de conservación. Feito en PRFV, polo que non precisa cuberto de retención. Non se observan fugas. Está comunicado co deposito de homoxeneización 1 e recibirá as augas do reactor biolóxico.','1.0');
