INSERT INTO equipos VALUES(767,4,NULL,'36058_01DNIV02','VBOA','Medidor de nivel. Arranque','Pozo de cabeceira','1','-','-','-',NULL,NULL,'-','Xeral','Boia',NULL,47,'Medidor de nivel de boia situado nunha nuha cota próxima ao punto de alivio. Esta boia fai arrancar o bombeo.','1.0');
