INSERT INTO equipos VALUES(867,4,NULL,'36820_01BOCA01','PCAL','Bomba 1','Pozo de cabeceira - Bombeo','2+1','Flygt','FP3171.180','510100',NULL,NULL,'18,5','Esencial','Centrífuga somerxible',NULL,58,'Funcionamento sen incidencias. Proceso de izado da bomba lento ao non dispor de polipasto eléctrico e que as correas do xogo de poleas manual non son o suficientemente longas.','1.0');
INSERT INTO equipos VALUES(868,4,NULL,'36820_01BOCA02','PCAL','Bomba 2','Pozo de cabeceira - Bombeo','2+1','Flygt','FP3171.180','510101',NULL,NULL,'18,5','Esencial','Centrífuga somerxible',NULL,58,'No momento da auditoría o equipo non funciona en automático nin en manual. Soamente arranca forzando o contactor. Presenza de fías que atascan a bomba. O rodete de aspiración presenta certos puntos de deterioro, pero que non comprometen o funcionamento. Proceso de izado da bomba lento ao non dispor de polipasto eléctrico e que as correas do xogo de poleas manual non son o suficientemente longas.','1.0');
INSERT INTO equipos VALUES(869,4,NULL,'36820_01BOCA03','PCAL','Bomba 3','Pozo de cabeceira - Bombeo','2+1','Flygt','FP3171.180','510102',NULL,NULL,'18,5','Esencial','Centrífuga somerxible',NULL,58,'Hai presenza de bastantes fías atascando as mesmas. O rodete presenta dúas pequenas roturas.O soporte superior das guías presentan certo grado de corrosión. Proceso de izado da bomba lento ao non dispor de polipasto eléctrico e que as correas do xogo de poleas manual non son o suficientemente longas.','1.0');
