INSERT INTO equipos VALUES(874,4,NULL,'36820_01TRIT01','PCAL','Trituradora 1','Pozo de cabeceira - Trituradoras','1+1','Flygt','FP3152.350','510014',NULL,NULL,'7,5','Esencial','Somerxible',NULL,58,'Funcionamento sen incidencias tanto en automático como en manual. Proceso de izado da bomba lento ao non dispor de polipasto eléctrico e que as correas do xogo de poleas manual non son o suficientemente longas.','1.0');
