INSERT INTO equipos VALUES(888,4,NULL,'36820_01EPOL02','PCAL','Axitador','Estación preparación POLI','1','ATX Motors (Motor)','-','-',NULL,NULL,'0,55','','Vertical',NULL,62,'Obsérvase en bo estado. Non aparece o axitador no SCADA, pero sí a estación de preparación de poli. A placa de características do motor non permite ler tódalas característcias.','1.0');
INSERT INTO equipos VALUES(889,4,NULL,'36820_01EPOL03','PCAL','Dosificador','Estación preparación POLI','1','ATX Motors (Motor)','-','-',NULL,NULL,'0,37','','Volumétrico',NULL,62,'Obsérvase en bo estado. Non aparece o dosificador no SCADA, pero sí a estación de preparación de poli. A placa das imaxes corresponde ao motor, a cal non deixa ler tódalas caracetrístcias con claridade. Na parte visible, dedúcese a o motor pode xirar a 2740 rpm traballando a 50 Hz.','1.0');
INSERT INTO equipos VALUES(890,4,NULL,'36820_01DEPO03','PCAL','Depósito de mestura','Liña de deshidratación','1','-','-','-',NULL,NULL,'-','','Lodo e POLI',NULL,62,'Depósito situado entre o depósito espesador de lodos e o filtro banda. Obsérvase en bo estado, sen presentar fugas.','1.0');
INSERT INTO equipos VALUES(891,4,NULL,'36820_01AGIT03','PCAL','Axitador','Liña de deshidratación','1','MRS (Motor)','IE-71M14 (Motor)','19011511',NULL,NULL,'0,25','Xeral','Vertical',NULL,63,'Sobresae un elemento móbil da redutora. A cobertura de protección do cable de sinal está roto. Funcionamento sen anomalías. A placa encóntrase cun alto grado de desgaste, polo que non é posible ler tódalas características do equipo, os datos recóllense do inventario previo.','1.0');
INSERT INTO equipos VALUES(892,4,NULL,'36820_01BOFD01','PCAL','Bomba lodo a deshidratación','Liña de deshidratación - Lodo a deshidratación','1','Mono-Dresser','CB0XKAE2R1/G','C57388/01',NULL,NULL,'1,1','Crítico','Parafuso helicoidal',NULL,63,'O estátor obsérvase en bo estado. A caixa de conexións está rota. A placa encóntrase gastada e non se pode ler con claridade. Apoiada sobre soportes metálicos. O variador indica unha frecuencia de 32.9 Hz.','1.0');
INSERT INTO equipos VALUES(893,4,NULL,'36820_01BOPF01','PCAL','Bomba purga','Purga de lodos liña de flotación','1','Mono-Dresser','CB04KAC1R1/X','C016138/07',NULL,NULL,'2,2','Crítico','Parafuso helicoidal',NULL,63,'Presenta unha rotura na brida por onde se aspiran os lodos e identifícase unha fuga entre motorredutora e rupo. A potencia mantense do inventario previo porque non se le na placa de características do equipo.','1.0');
INSERT INTO equipos VALUES(894,4,NULL,'36820_01DEPO04','PCAL','Depósito','Liña de lodos - Acumulador','1','Cortiplas','-','387-04',NULL,NULL,'-','Crítico','PRFV',NULL,63,'Obsérvase en bo estado, sen presenza de fugas.','1.0');
INSERT INTO equipos VALUES(895,4,NULL,'36820_01FIBA01','PCAL','Filtro banda','Liña de deshidratación','1','Tefsa','MS-10','477 PT-70293',NULL,NULL,'1,1','Crítico','Tela filtrante',NULL,63,'Non se observan incidencias. Bo funcionamento, bo estado de conservación e mantemento. Desgaste nos laterais da tela fíltrante pero que non impide o correcto funcionamiento do proceso de deshidratación. Non se localiza a placa coas características, polo que os datos do equipo consérvanse do inventario previo. O variador indica unha frecuencia de 51.4 Hz.','1.0');
