INSERT INTO equipos VALUES(897,4,NULL,'36820_01BOAI01','PCAL','Bomba','Auga de servizo','1','Saci','JET 15 M','102165060',NULL,NULL,'1,6','Crítico','Autoaspirante',NULL,66,'Bomba que subministra auga de servizo a planta. Atópase á cota do río. A altura de traballo comprende entre os 38-58 metros, sendo a altura máxima da bomba de 61 metros. Conta con presostato e manómetro. A presión máxima de traballo do presosteto é de 10 bar. O manómetro indica 3 bar.','1.0');
