INSERT INTO equipos VALUES(900,4,NULL,'36820_01COMP01','PCAL','Transportador compactador','Pretratamento','1','Rotowater','ROT TCSI','VN3656',NULL,NULL,'0,75','Xeral','Parafuso sinfín',NULL,59,'Funcionamento sen incidencias, actívase automáticamente. O equipo conta cun motor. As características do motor son as seguintes: Marca: CEMER. Modelo: IE1-MSE802-4.','1.0');
INSERT INTO equipos VALUES(901,4,NULL,'36820_01DEPO01','PCAL','Depósito','Homoxeneización','1','Cortiplas','-','385-04',NULL,NULL,'-','Crítico','PRFV',NULL,59,'Bo estado superficial do depósito. Non precisa cuberto de retención. Indícase que, na condución dende o depósito ata a cámara de rotura na liña de tratamento FQ, deposítanse areas. Pensa que pode resolverse elevando a cota de saída do depósito. Faltan parafusos na xunta do tubo de saída co depósito. A placa coas características é pouco lexible, polo que se conservan os datos do inventario previo.','1.0');
INSERT INTO equipos VALUES(902,4,NULL,'36820_01DESF01','PCAL','Desbaste de finos liña 1','Pretratamento','2','Rotowater','ROT 630/700/1','VN3495',NULL,NULL,'0,55','Crítico','Rotocriba',NULL,59,'Funcionamento automático. Na xunta da tubaxe de saída da auga filtrada ata o depósito de homoxeneización faltan parafusos. O equipo conta cun motor. As características do motor son as seguintes: Marca: ATX motors. Modelo: MOT 3PH-MT80M2-6.','1.0');
INSERT INTO equipos VALUES(903,4,NULL,'36820_01DESF02','PCAL','Desbaste de finos liña 2','Pretratamento','2','Rotowater','ROT 630/700/1','VN3496',NULL,NULL,'0,55','Crítico','Rotocriba',NULL,59,'Bo estado, funcionamento sen vibacións nin ruídos anómalos. Na xunta da tubaxe de saída da auga filtrada ata o depósito de homoxeneización faltan parafusos. Funcionamento automático. O equipo conta cun motor. As características do motor son as seguintes: Marca: CEMER. Modelo: IE1-MSE6D2-6.','1.0');
INSERT INTO equipos VALUES(904,4,NULL,'36820_01BOTU01','PCAL','Bomba turbidez','Pozo de rexistro previo á saída','1','-','-','-',NULL,NULL,'-','Esencial','Centrífuga',NULL,64,'Fora de servizo','1.0');
INSERT INTO equipos VALUES(905,4,NULL,'36820_01CCM01','PCAL','Manobra e proteccións xerais','Sala de control','1','-','-','-',NULL,NULL,'-','Crítico','Principal',NULL,64,'A modo xeral, bo estado. Na parte baixa atópanse os cables soltos pero a disposición no cadro e nas canaletas de protección é correcta.','1.0');
