INSERT INTO equipos VALUES(908,4,NULL,'36820_01CCM04','PCAL','Manobra e proteccións xerais','Liña de deshidratación','1','-','-','-',NULL,NULL,'-','Crítico','Filtro banda',NULL,64,'Presenta certo grado de condensación. Descolocadas as canaletas de protección do cableado. Cables atravesando o panel por diante de diferentes elementos do cadro.','1.0');
INSERT INTO equipos VALUES(909,4,NULL,'36820_01CCM05','PCAL','Manobra e proteccións xerais','Pozo de cabeceira','1','-','-','-',NULL,NULL,'-','','Trituradoras e bombas',NULL,64,'Cableado desordenado e fóra das canaletas. Proteccións de canaletas retiradas. Non hai esquemas nas portas dos cadros. Dispositivo de protección xeral para apertura da porta fóra de servizo. O variados de frecuencia, no momento da auditoría marca un funcionamento a 46Hz e un consumo de 16A. A parte externa do ventilador está rota. O funcionamento xeral é bo, identificando arranques e paros das diferentes trituradoras e bombas de cabeceira. Unicamente da fallo o arranque en automático e en manual da bomba de cabeceira 2, pero que arranca se se fai contacto no contactor.','1.0');
INSERT INTO equipos VALUES(910,4,NULL,'36820_01CCM06','PCAL','Manobra e proteccións xerais','Pretratamento','1','-','-','-',NULL,NULL,'-','','Parafuso transportador compactador',NULL,64,'','1.0');
