INSERT INTO equipos VALUES(947,4,NULL,'36053_02BOCA01','SOUT','Bomba 1','Pozo de cabeceira','1+1','Sulzer','ABS XFP-PE2-100E-CB1.3-PE60_4E-EX','300351539 2970373',NULL,NULL,'6,7','Esencial','Centrífuga somerxible',NULL,67,'Funcionamento sen anomalías e sen incidencias segundo o operario.','1.0');
INSERT INTO equipos VALUES(948,4,NULL,'36053_02BOCA02','SOUT','Bomba 2','Pozo de cabeceira','1+1','Sulzer','ABS XFP-PE2-100E-CB1.3-PE60_4E-EX','300849633 3473670',NULL,NULL,'6,7','Esencial','Centrífuga somerxible',NULL,67,'Funcionamento sen incidencias segundo o operario. Bo estado de conservación.','1.0');
INSERT INTO equipos VALUES(949,4,NULL,'36053_02BODA01','SOUT','Bomba 1','Sistema DAC 1','1','Nocchi','VLR 8','-',NULL,NULL,4.0,'Esencial','Multicelular vertical',NULL,69,'É a única das dúas bombas do calderín da liña 1 que ten as conexións feitas. Este sistema de DAC está fóra de uso, so se emprega o da liña 2. Non presenta placa coas características do equipo, polo que se recollen os datos do inventario previo.','1.0');
INSERT INTO equipos VALUES(950,4,NULL,'36053_02BODA02','SOUT','Bomba 2','Sistema DAC 1','1','ATX Motors (Motor)','-','-',NULL,NULL,11.0,'Esencial','Centrífuga Monoblock',NULL,69,'Bomba en reparación. Sistema fóra de uso. A placa coas características do equipo non é lexible. Identifícase na placa do motor que é de marca ATX Motors e ten unha potencia de 11 kW.','1.0');
INSERT INTO equipos VALUES(951,4,NULL,'36053_02BODA03','SOUT','Bomba 1','Sistema DAC 2','1','Soldalux','SLX MAT 3','-',NULL,NULL,11.0,'Esencial','Centrífuga Monoblock',NULL,69,'Bomba en funcionamento. Recolle auga clarificada da liña 2 para sobresaturala no calderín. Bo estado de conservación. Manchas de sucidade pero poden ser debidas ás actuacións das obras de mellora. A placas coas características do equipo non é lexible, pero vese o nome de Soldalux. A placa do motor tampouco é lexible, pero pódese identificar que a marca do motor é ATX Motors e ten unha potencia de 11 kW. O modelo obtense da descrición das instalacións aportada pola AT.','1.0');
INSERT INTO equipos VALUES(952,4,NULL,'36053_02BODA04','SOUT','Bomba 2','Sistema DAC 2','1','Nocchi','VLR 8','-',NULL,NULL,4.0,'Esencial','Multicelular vertical',NULL,69,'Equipo retirado. Os datos das características recóllense do inventario previo.','1.0');
INSERT INTO equipos VALUES(953,4,NULL,'36053_02BODO01','SOUT','Bomba dosificadora','Bomba coagulante 1 L1','1+1','Grundfos Alldos','DMX 27 10 AR PVC/V/G S G1B1B1F','11/096316',NULL,NULL,'0,09','Esencial','Membrana',NULL,71,'Funcionamento sen vibracións nin ruídos anómalos. Conectada a toma de corriente. Puntos de corrosión e sucidade. Cable de sinal sen enchufar.','1.0');
INSERT INTO equipos VALUES(954,4,NULL,'36053_02BODO02','SOUT','Bomba dosificadora','Bomba coagulante 2 L1','1+1','Grundfos Alldos','DMX 27-10 AR-PVC/V/G-S-G1B1B1F','08/24737',NULL,NULL,'0,09','Esencial','Membrana',NULL,71,'Mesma bomba que a número 1 da liña 1. Sen enchufar o cable de sinal. Conectada a toma de corrente común. Cuberta do ventilador moi deteriorada. Auditoria 2022. Non está na planta.','1.0');
INSERT INTO equipos VALUES(955,4,NULL,'36053_02BODO03','SOUT','Bomba dosificadora','Bomba coagulante 1 L2','1+1','Seko','MS1B108A31H4000','-',NULL,NULL,'0,25','Esencial','Membrana',NULL,71,'Bo estado pero con puntos de corrosión. Conectada a toma de corrente común. Sen enchufar o cable de sinal. As características do motor son as seguintes: Marca: SACEMI-GAMAR. Modelo: ZCO-71-5B40ACS. Número de serie: 21-118317.','1.0');
INSERT INTO equipos VALUES(956,4,NULL,'36053_02BODO04','SOUT','Bomba dosificadora','Bomba coagulante 2 L2','1+1','Seko','MS1B108A31H4000','-',NULL,NULL,'0,25','Esencial','Membrana',NULL,71,'Bo estado pero con puntos de corrosión. Conectada a toma de corrente común. Sen enchufar o cable de sinal. As características do motor son as seguintes: Marca: SACEMI-GAMAR. Modelo: ZCO-71-5B40ACS. Número de serie: 21-118317.','1.0');
INSERT INTO equipos VALUES(957,4,NULL,'36053_02BODO05','SOUT','Bomba dosificadora','Bomba floculante 1 L1','1+1','Alldos','PRIMUS','-',NULL,NULL,'0,25','Esencial','Membrana',NULL,71,'Obsérvase en bo estado. Protección de cableado roto, cables expostos. As características do motor son as seguintes: Marca: ATX motors, de 0.25kW e velocidade de rotación 2840rpm.','1.0');
