INSERT INTO equipos VALUES(978,4,NULL,'36053_02CCM05','SOUT','Manobra e proteccións xerais','Liña de deshidratación','1','-','-','-',NULL,NULL,'-','Crítico','Filtro banda',NULL,73,'Cuadro previsto para conservación para uso de filtro banda como equipo de reserva para novo decantador centrífugo.','1.0');
INSERT INTO equipos VALUES(979,4,NULL,'36053_02COPR01','SOUT','Compresor','Liña pneumática','1','Atlas Copco','-','-',NULL,NULL,'7,5','Esencial','De pistón',NULL,69,'Non está funcionando no momento da realización da auditoría. Presenta sinais de corrosión. A placa de características do equipo non é lexible. O operario indica que funciona sen problemas, arrancando e parando automáticamente. O motor presenta as seguintes características: Marca: LEROY SOMER. Modelo: LS132M. Número: ML07540KK001.','1.0');
INSERT INTO equipos VALUES(980,4,NULL,'36053_02COPR02','SOUT','Compresor','Liña pneumática','1','Atlas Copco','LE10-10UV TM 270 CE','ITR 1049209',NULL,NULL,'7,14','Esencial','De pistón',NULL,69,'Arranques e paros automáticos durante a auditoría. Sen vibracións nin ruídos anómalos. As características do motor son as seguintes: Marca: LEROY SOMER. Modelo: LS132M. Número de serie: 240804. Potencia: 7.5 kW.','1.0');
INSERT INTO equipos VALUES(981,4,NULL,'36053_02DEPO01','SOUT','Depósito','Homoxeneización 1','1','-','-','-',NULL,NULL,'-','Crítico','PRFV',NULL,68,'Depósito 1 de homoxeneización. Recibe a auga filtrada do pretratamento e alimenta ao depósito 2 cunha tubaxe que non ten válvula de seccionamento. Auditoría 2022. Non sae auga dende a tubaxe de vaciado, aínda ca válvula aberta. ','1.0');
INSERT INTO equipos VALUES(982,4,NULL,'36053_02DEPO02','SOUT','Depósito','Homoxeneización 2','1','-','-','-',NULL,NULL,'-','Crítico','PRFV',NULL,68,'Segundo de pósito de homoxeneización que recibe as augas do depósito 1. Dende este depósito aliméntanse as liñas de tratamento FQ. A saída cara estas liñas está controlada con válvulas pneumáticas de talladeira. Saída pola parte superior. Conta cun aliviadoiro.','1.0');
INSERT INTO equipos VALUES(983,4,NULL,'36053_02DEPO03','SOUT','Depósito','Almacenamiento PAX','1','-','-','-',NULL,NULL,'-','Crítico','PRFV',NULL,71,'A placa coas características encóntrase despegada.','1.0');
INSERT INTO equipos VALUES(984,4,NULL,'36053_02DEPO04','SOUT','Depósito','Liña de lodos - Acumulador','1','-','-','-',NULL,NULL,'-','Crítico','PRFV',NULL,72,'Recibe os lodos das bombas de purga pola parte superior. Retira os lodos cara a deshidratación pola parte inferior cunha bomba mono.','1.0');
INSERT INTO equipos VALUES(985,4,NULL,'36053_02DEPO05','SOUT','Depósito de mestura','Liña de deshidratación','1','-','-','-',NULL,NULL,'-','-','Lodo e POLI',NULL,72,'Ao depósito chega a mestura de lodo e poli, que se dosifica á saída da bomba mono que transporta os lodos cara a liña de deshidratación. Entrada de mestura pola parte baixa, saída pola parte superior. Elevado para mellorar o comportamento do fluxo de saída á altura do filtro banda.','1.0');
INSERT INTO equipos VALUES(986,4,NULL,'36053_01DESF01','SOUT','Desbaste de finos','Zona pretratamento e  deshidratación','2','ABB','M24A112M-6','-',NULL,NULL,'-','Crítico','Masko Zoll',NULL,68,'Equipo retirado. Características recollidas do inventario previo.','1.0');
