INSERT INTO equipos VALUES(989,4,NULL,'36053_02DEUV01','SOUT','Equipo desinfección UV','Final liña de auga','1','Trojan','Logic 18AM40','1710671207',NULL,NULL,'4,35','Crítico','Tubo pechado a baixa presión',NULL,70,'18 lámpadas segundo o panel do cadro. Funciona en continuo. Ten sinal no SCADA, pero o esquema do SCADA é dun canal UV, diferente ao equipo que está instalado.','1.0');
