INSERT INTO equipos VALUES(994,4,NULL,'36053_01EDIF03','SOUT','Sala de control','Edificio principal','1','-','-','-',NULL,NULL,'-','','Obra civil',NULL,75,'No momento da auditoría observáronse conxuntos de caixas apiladas, así como o cableado solto. Isto debido a realización das obras de mellora da EDAR, sendo esta unha situación temporal.','1.0');
