INSERT INTO equipos VALUES(1030,4,NULL,'36053_02VALV06','SOUT','Válvula de seccionamento','Válvula de fondo L1','1','-','-','-',NULL,NULL,'-','Xeral','Talladeira pneumática',NULL,74,'Obsérvase en bo estado con sinais de corrosión. Non presenta fugas estando pechada.','1.0');
INSERT INTO equipos VALUES(1031,4,NULL,'36053_02VALV07','SOUT','Válvula de seccionamento','Válvula de fondo L2','1','-','-','-',NULL,NULL,'-','Xeral','Talladeira pneumática',NULL,74,'Non presenta fugas estando pechada. Non se emprega a cotío ao igual que o parafuso de fondo de liña. Á botoneira da electroválvula que controla o actuador pneumático fáltanlle etiquetas de sinalización.','1.0');
INSERT INTO equipos VALUES(1032,4,NULL,'36053_02BARR01','SOUT','Varredora','Liña de flotación 1','1','ABB/Spaggiari (Motor)','-','-',NULL,NULL,'0,18','Crítico','Cadea-piñón',NULL,69,'Presenta unha cuberta do sistema de desodorización. Non está funcionando no momento da realización da auditoría. Arranca en manual. Obsérvase en bo estado. Sen acceso á placa das características do equipo, polo que os datos recóllense do inventario previo. Botoneira sen etiquetar. Non ten tapa cubrindo o ventilador e presenta un alto grado de degaste da pintura.','1.0');
INSERT INTO equipos VALUES(1033,4,NULL,'36053_02BARR02','SOUT','Varredora','Liña de flotación 2','1','Spaggiari (Motor)','T63B-4 (Motor)','-',NULL,NULL,'0,18','Crítico','Cadea-piñón',NULL,69,'Cámara de floculación tapada coa cuberta do sistema de desodorización. Dificultade para inspeccionar tódalas rasquetas e o estado do conxunto da cadea pola cuberta de desodorización. Carcasa do ventilador do motor rota. Grupo motorredutor con puntos de corrosión e sucidade. Botoneira indica que funciona en manual. Identifícase a placa do motor, de marca Spaggiari, de potencia 0.18 kW. Os datos mostrados son os da placa do motor da varredora.','1.0');
INSERT INTO equipos VALUES(1034,4,NULL,'36053_02VERT01','SOUT','Vertedoiro','Final de L1','1','-','-','-',NULL,NULL,'-','Xeral','Accionamiento manual',NULL,69,'Obsérvase en bo estado. Nivel do vertedoiro máis alto que o da liña 2. Mal estado das electroválvulas que activan o movemento do vertedoiro.','1.0');
