INSERT INTO equipos VALUES(1545,4,NULL,'15072_01EDIF04','RIXO','Obra civil','Zona de almacenamento de residuos','1','','','',NULL,NULL,'','','',NULL,76,replace('Restos de corrosión no chan derivado das placas protectoras.\nFormación de pozas de auga por falta de pendientes.\nPresencia de corrosión e falta de pintura na estrutura metálica da cubierta.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(1546,4,NULL,'15072_01EDIF05','RIXO','Obra civil','Cámara de bombeo','1','','','',NULL,NULL,'','','',NULL,76,'Non se puido acceder por presenza de auga residual. Tomáronse varias fotografías desde o punto de acceso e a obra civil do interior da cámara de bombeo semella presentar un estado normal, acorde ao seu uso.','1.0');
