INSERT INTO equipos VALUES(1548,4,NULL,'15072_01EDIF07','RIXO','Obra civil','Cámara seca do bombeo','1','','','',NULL,NULL,'','','',NULL,76,replace('Presencia de humidades na zona da porta de acceso desde o exterior.\nTamén presenta humidades na parede posterior ao redor de posibles puntos de drenaxe ou inxección, así como no chan ao redor da zona das bombas.\nPresencia de salitre e principios de infiltracións, especialmente no nivel inferior. Deberse controlar o avance das posibles infiltracións.','\n',char(10)),'1.0');
INSERT INTO equipos VALUES(1549,4,NULL,'15072_01EDIF08','RIXO','Obra civil','Sala do grupo electróxeno','1','','','',NULL,NULL,'','','',NULL,76,replace('Presencia de auga no chan onde o grupo electróxeno, que aparentemente entra pola reixa de ventilación. Tamén se aprecia humidade ao pe da outra reixa de ventilación.\nEmprego tamén como almacenamiento de material.','\n',char(10)),'1.0');
