INSERT INTO equipos VALUES(1583,4,NULL,'15072_01EDIF41','RIXO','Obra civil','Almacén','1','','','',NULL,NULL,'','','',NULL,88,replace('Mesmo edificio que o taller.\nOs botes de pintura, piedras,  vertedoiro regulable con contrapeso, aislamento e a estantería son da planta. O resto de material é da empresa explotadora.','\n',char(10)),'1.0');
