INSERT INTO equipos VALUES(1585,4,NULL,'15072_01EDIF43','RIXO','Obra civil','Urbanización','1','','','',NULL,NULL,'','','',NULL,88,replace('Como principal problema, detectouse a falta de vallado perimetral entre o muro do decantador 2 e a desodorización, xa que o peche vexetal non impide o acceso a intrusos. Tamén se observou a existencia dunha pintada pola parte de fóra do valor situado onde o almacén.\nPresencia de vasoira na zona ajardinada do decantador 2, aparentemente tirada desde o exterior.\nA urbanización interior da parcela atópase en bo estado.','\n',char(10)),'1.0');
